defmodule GameSimulator.Traversal.OfficialTest do
  use ExUnit.Case, async: true
  alias GameSimulator.Traversal.Game

  # Data generated by executing the public official rules runtime on 25 Oct 2026.
  # No third-party implementation is included. Compare observable legal play.
  test "independent official corpus: 1440 legal actions and 16 transitions on varied terrain" do
    cases = Path.expand("../../fixtures/traversal_official.json", __DIR__) |> File.read!() |> Poison.decode!()
    for fixture <- cases do
      state = decode_state(fixture["state"])
      actual = Game.actions(state) |> Enum.map(&[&1.piece, &1.row, &1.col, &1.kind]) |> Enum.sort()
      assert actual == Enum.sort(fixture["legal"]), fixture["name"]
      [id, row, col] = fixture["chosen"]
      {:ok, next} = Game.play(state, id, row, col)
      expected = decode_state(fixture["next"])
      assert observable(next) == observable(expected), fixture["name"]
    end
  end

  def decode_state(raw) do
    pieces = Enum.map(raw["pieces"], fn p -> Map.new(p, fn {k, v} -> {String.to_existing_atom(k), v} end) end)
    %{board: raw["board"], pieces: pieces, turn: raw["turn"], moves: raw["moves"], exited: raw["exited"], scores: raw["scores"], result: raw["result"], history: []}
  end

  def observable(state) do
    pieces = Enum.map(state.pieces, fn p -> if p.status == "active", do: {p.id, p.status, p.row, p.col}, else: {p.id, p.status} end) |> Enum.sort()
    winner = if state.result, do: Map.get(state.result, :winner, Map.get(state.result, "winner")), else: nil
    {pieces, state.turn, state.moves, state.exited, state.scores, winner}
  end
end
